// @pit: {"label": "Compute analog alignments, best-fit lag search, drawdowns, rolling returns, CAPE series"}
async ({ http: { request } }) => {
  const H = { "User-Agent": "Mozilla/5.0" };
  const y = (s: string) => `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(s)}?period1=473385600&period2=1794787200&interval=1mo`;
  const [a, b, m] = await Promise.all([request(y("^GSPC"), { maxBytes: 1_000_000, headers: H }), request(y("^IXIC"), { maxBytes: 1_000_000, headers: H }), request("https://www.multpl.com/shiller-pe/table/by-month", { maxBytes: 1_000_000, headers: H })]);
  const parse = (body: string) => { const j = JSON.parse(body).chart.result[0]; const mp = new Map<string, number>(); j.timestamp.forEach((t: number, i: number) => { const c = j.indicators.quote[0].close[i]; if (c != null) mp.set(new Date(t * 1000 + 86400000 * 3).toISOString().slice(0, 7), c); }); return mp; };
  const spx = parse(a.body), ndx = parse(b.body);
  const months = [...spx.keys()].sort();
  const idx = (k: string) => months.indexOf(k);
  const S = months.map((k) => spx.get(k)!), N = months.map((k) => ndx.get(k) ?? null);
  const r2 = (x: number) => Math.round(x * 100) / 100;
  const pct = (x: number) => r2((x - 1) * 100);
  const win = (arr: (number | null)[], s: number, n: number) => arr.slice(s, s + n) as number[];
  const stats = (arr: (number|null)[], s: number, n: number) => {
    const w = win(arr, s, n); let peak = w[0], mdd = 0; const rets: number[] = [];
    for (let i = 0; i < w.length; i++) { peak = Math.max(peak, w[i]); mdd = Math.min(mdd, w[i] / peak - 1); if (i) rets.push(Math.log(w[i] / w[i - 1])); }
    const mu = rets.reduce((p, c) => p + c, 0) / rets.length; const sd = Math.sqrt(rets.reduce((p, c) => p + (c - mu) ** 2, 0) / (rets.length - 1));
    return { from: months[s], to: months[s + n - 1], start: r2(w[0]), end: r2(w.at(-1)!), gainPct: pct(w.at(-1)! / w[0]), cagrPct: pct((w.at(-1)! / w[0]) ** (12 / (n - 1))), volPct: r2(sd * Math.sqrt(12) * 100), maxDDPct: r2(mdd * 100) };
  };
  const now = months.length - 1; const cur0 = idx("2022-11"); const n = now - cur0 + 1; // 49
  const corr = (x: number[], z: number[]) => { const mx = x.reduce((p, c) => p + c) / x.length, mz = z.reduce((p, c) => p + c) / z.length; let sxz = 0, sx = 0, sz = 0; x.forEach((v, i) => { sxz += (v - mx) * (z[i] - mz); sx += (v - mx) ** 2; sz += (z[i] - mz) ** 2; }); return sxz / Math.sqrt(sx * sz); };
  const logPath = (arr: number[]) => arr.map((v) => Math.log(v / arr[0]));
  const rets = (arr: number[]) => arr.slice(1).map((v, i) => Math.log(v / arr[i]));
  const curW = win(S, cur0, n);
  const scan: { start: string; levelCorr: number; retCorr: number; rmse: number; gainPct: number; monthsToPeak: number }[] = [];
  const peakNdx = idx("2000-03");
  for (let s = idx("1987-01"); s + n - 1 <= idx("2002-12"); s++) {
    const w = win(S, s, n); const lp = logPath(w), lc = logPath(curW);
    const rmse = Math.sqrt(lp.reduce((p, v, i) => p + (v - lc[i]) ** 2, 0) / n);
    scan.push({ start: months[s], levelCorr: r2(corr(lp, lc) * 1000) / 1000 * 1, retCorr: Math.round(corr(rets(w), rets(curW)) * 1000) / 1000, rmse: Math.round(rmse * 1000) / 1000, gainPct: pct(w.at(-1)! / w[0]), monthsToPeak: peakNdx - (s + n - 1) });
  }
  const byRmse = [...scan].sort((p, q) => p.rmse - q.rmse).slice(0, 6);
  const byRet = [...scan].sort((p, q) => q.retCorr - p.retCorr).slice(0, 4);
  const netscape = idx("1995-08");
  const analogA = { spx: stats(S, netscape, n), ndx: stats(N, netscape, n), spxCur: stats(S, cur0, n), ndxCur: stats(N, cur0, n),
    levelCorr: Math.round(corr(logPath(win(S, netscape, n)), logPath(curW)) * 1000) / 1000, retCorr: Math.round(corr(rets(win(S, netscape, n)), rets(curW)) * 1000) / 1000 };
  // Forward path from analog end (1999-08) to 2002-10 low
  const fwd = (s0: number) => { const e = s0 + n - 1; const base = S[e]; let mx = 0, mxAt = "", mn = 9, mnAt = ""; for (let i = e; i <= idx("2002-12"); i++) { const r = S[i] / base; if (r > mx) { mx = r; mxAt = months[i]; } if (r < mn) { mn = r; mnAt = months[i]; } } return { analogToday: months[e], furtherUpPct: pct(mx), peakMonth: mxAt, troughFromTodayPct: pct(mn), troughMonth: mnAt }; };
  // rolling 5y CAGR (60 months) for SPX, quarterly samples since 1990
  const roll: [string, number][] = []; for (let i = idx("1990-01"); i <= now; i += 3) roll.push([months[i], pct((S[i] / S[i - 60]) ** (1 / 5))]);
  const rollMax90s = roll.filter(([k]) => k < "2003").sort((p, q) => q[1] - p[1])[0];
  const rollNow = pct((S[now] / S[now - 60]) ** (1 / 5)); const roll3Now = pct((S[now] / S[now - 36]) ** (1 / 3));
  const roll3_99 = pct((S[idx("1999-08")] / S[idx("1996-08")]) ** (1 / 3)); const roll5_99 = pct((S[idx("1999-08")] / S[idx("1994-08")]) ** (1 / 5));
  // CAPE from multpl
  const txt = m.body.replace(/<[^>]+>/g, " ").replace(/&#x2002;/g, " ").replace(/\s+/g, " ");
  const cape: Record<string, number> = {}; for (const mm of txt.matchAll(/([A-Z][a-z]{2}) (\d{1,2}), (\d{4}) (\d+\.\d+)/g)) { const mo = "JanFebMarAprMayJunJulAugSepOctNovDec".indexOf(mm[1]) / 3 + 1; const k = `${mm[3]}-${String(mo).padStart(2, "0")}`; if (!(k in cape)) cape[k] = +mm[4]; }
  const capeSel = Object.entries(cape).filter(([k]) => k >= "1990-01" && /-(01|07)$/.test(k)).sort();
  // NDX/SPX ratio
  const ratio = (k: string) => r2(ndx.get(k)! / spx.get(k)!);
  return { n, analogA, fwdA: fwd(netscape), byRmse: byRmse.map((x) => ({ ...x, ...fwd(idx(x.start)) })), byRet, rollMax90s, rollNow, roll3Now, roll3_99, roll5_99, roll: roll.filter((_, i) => i % 2 === 0), capeCount: Object.keys(cape).length, capeSel, ratio: { "1995-08": ratio("1995-08"), "1999-08": ratio("1999-08"), "2000-03": ratio("2000-03"), "2022-11": ratio("2022-11"), now: ratio(months[now]) }, lastMonth: months[now], spx2000: { "2000-03": spx.get("2000-03"), "2000-08": spx.get("2000-08"), "2002-09": spx.get("2002-09") } } as PitJsonValue;
}
